def run_trial(seed: int) -> dict:
    random.seed(seed)

    def gaussian_elimination(A, b):
        n = len(A)
        for i in range(n):
            # Find max pivot in column i
            max_idx = i
            for j in range(i+1, n):
                if abs(A[j][i]) > abs(A[max_idx][i]):
                    max_idx = j
            A[i], A[max_idx] = A[max_idx], A[i]
            b[i], b[max_idx] = b[max_idx], b[i]

            # Eliminate column i for all rows below i
            for j in range(i+1, n):
                factor = -A[j][i] / A[i][i]
                for k in range(i, n):
                    A[j][k] += factor * A[i][k]
                b[j] += factor * b[i]

        # Back-substitution
        x = [0] * n
        for i in range(n-1, -1, -1):
            x[i] = (b[i] - sum(A[i][j] * x[j] for j in range(i+1, n))) / A[i][i]
        return x

    def matrix_multiply(A, B):
        m, n = len(A), len(B[0])
        p = len(B)
        C = [[0] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                for k in range(p):
                    C[i][j] += A[i][k] * B[k][j]
        return C

    def determinant(A):
        if len(A) == 1:
            return A[0][0]
        det = 0
        sign = 1
        for j in range(len(A)):
            submatrix = [row[:j] + row[j+1:] for row in A[1:]]
            det += sign * A[0][j] * determinant(submatrix)
            sign *= -1
        return det

    def linear_algebra_solver(A, b):
        det_A = determinant(A)
        if det_A == 0:
            return None
        x = [Fraction(0) for _ in range(len(A))]
        for i in range(len(A)):
            A_i = [row[:i] + row[i+1:] for row in A]
            b_i = b[:]
            b_i[i] /= det_A
            A_i[i][i] = 1 / det_A
            x[i] = Fraction(b_i[i])
        return x

    def generate_tseitin_formula(n):
        variables = list(range(1, n+1))
        clauses = []
        for i in range(1, n+1):
