                clauses.append([i, -j])
                clauses.append([-i, j])
                clauses.append([j, -i])
                clauses.append([-j, i])
        return variables, clauses

    def resolution_width(clauses):
        queue = set()
        for clause in clauses:
            if len(clause) == 1:
                queue.add(clause[0])
            elif len(clause) == 2:
                queue.add(clause[0])
                queue.add(-clause[1])
            else:
                return float('inf')
        while queue:
            literal = random.choice(list(queue))
            queue.remove(literal)
            for clause in clauses:
                if literal in clause:
                    new_clause = [l for l in clause if l != literal]
                    if len(new_clause) == 0:
                        return float('inf')
                    elif len(new_clause) == 1:
                        queue.add(new_clause[0])
        return len(queue)

