            clause = clauses[j]
            if len(clause) == 1:
                A[n + j][variables.index(abs(clause[0]))] = 1
                b[n + j] = -clause[0]
            elif len(clause) == 2:
                A[n + j][variables.index(abs(clause[0]))] = 1
                A[n + j][n + m + variables.index(abs(clause[1]))] = 1
                b[n + j] = clause[0] + clause[1]
            else:
                return float('inf')

